17	package org.springframework.samples.petclinic.util;
18	
19	import java.util.Map;
20	
21	/**
22	 * Derives the canonical region ('locality') for a city from a fixed city-to-region table.
23	 *
24	 * <p>The table pins {@code Sydney -> NSW}, {@code Melbourne -> VIC} and
25	 * {@code Brisbane -> QLD}. Any city not in the table (including {@code null})
26	 * derives the locality {@code "UNKNOWN"}.
27	 */
28	public abstract class Localities {
29	
30	    private static final Map<String, String> CITY_REGION =
31	        Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
32	
33	    /** Region keyed by the leading two digits of its postcode range (20xx, 30xx, 40xx). */
34	    private static final Map<Integer, String> POSTCODE_REGION =
35	        Map.of(20, "NSW", 30, "VIC", 40, "QLD");
36	
37	    /**
38	     * @param city the owner's city, may be {@code null}
39	     * @return the canonical region string, or {@code "UNKNOWN"} when the city is not in the table
40	     */
41	    public static String regionOf(String city) {
42	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
43	    }
44	
45	    /**
46	     * Prefers the postcode: a 4-digit postcode in a known range (NSW 2000-2099, VIC 3000-3099,
47	     * QLD 4000-4099) fixes the region. Otherwise falls back to the city-to-region table.
48	     *
49	     * @param city the owner's city, may be {@code null}
50	     * @param postcode the owner's postcode, may be {@code null}
51	     * @return the canonical region string, or {@code "UNKNOWN"} when neither resolves
52	     */
53	    public static String regionOf(String city, String postcode) {
54	        String byPostcode = regionOfPostcode(postcode);
55	        return byPostcode != null ? byPostcode : regionOf(city);
56	    }
57	
58	    private static String regionOfPostcode(String postcode) {
59	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
60	            return null;
61	        }
62	        return POSTCODE_REGION.get(Integer.parseInt(postcode) / 100);
63	    }
64	
65	}
