6	
7	/**
8	 * Derives an owner's {@code identityKey} and uses it as the single source of truth for
9	 * duplicate detection: {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}.
10	 *
11	 * <p>Two owners are duplicates only when their WHOLE identityKey matches; because the
12	 * telephone is part of the key, members of the same household with different telephones
13	 * carry different keys and are both allowed.
14	 */
15	public final class IdentityKeys {
16	
17	    private IdentityKeys() {
18	    }
19	
20	    /** The owner's derived identity key. The telephone is already stored normalised
21	     *  (E.164); a missing email or household id contributes an empty segment. */
22	    public static String of(Owner owner) {
23	        String email = owner.getEmail() == null ? "" : owner.getEmail();
24	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
25	        return owner.getTelephone() + "|" + email + "|" + householdId;
26	    }
27	
28	    /** Whether an existing owner shares the candidate's whole identity key. */
29	    public static boolean isDuplicate(Collection<Owner> existing, Owner candidate) {
30	        String key = of(candidate);
31	        return existing.stream().anyMatch(o -> key.equals(of(o)));
32	    }
33	}
